WITH SalesQuantity AS (SELECT ps.productcode, SUM(ps.quantity) AS slsqty, COUNT(DISTINCT ps.ID) AS Frequence, ps.storename FROM ProductSaleInformation ps INNER JOIN products p ON ps.Productcode = p.productcode AND ps.StoreName = p.StoreName WHERE ps.Transactiondate >= @ODATA AND ps.quantity > 0 AND ps.SeriesTransID = 1 AND ps.transactionvalidity = 0 AND p.isactive = 1 AND ps.DontConsiderInOrder = 0 AND ps.storename = @storename GROUP BY ps.productcode, ps.storename), MaxSalesQty AS (SELECT Productcode, MAX(Quantity) AS MaxSalesQtyInBill FROM ProductSaleInformation WHERE SeriesTransID = 1 AND transactionvalidity = 0 AND Transactiondate >= @ODATA AND storename = @storename GROUP BY Productcode), ProductSaleInfo AS (SELECT p.productcode, p.productname, p.TotalStock, p.SaleUnit, sq.slsqty, p.PurchasePrice, p.MRP, p.UnitDescription, p.SubLocation, p.producttype, CEILING(sq.slsqty / NULLIF(sq.Frequence, 0)) AS AvgSalesQty, m.MaxSalesQtyInBill, GETDATE() AS wanteddate, p.StoreName, @storecode AS storecode, CONVERT(VARCHAR(8), GETDATE(), 112) + RIGHT('0' + CONVERT(VARCHAR(2), DATEPART(MINUTE, GETDATE())), 2) + RIGHT('0' + CONVERT(VARCHAR(2), DATEPART(SECOND, GETDATE())), 2) AS OrderID, CASE WHEN CEILING((sq.slsqty / 90.0) * @minday) < CEILING(sq.slsqty / NULLIF(sq.Frequence, 0)) THEN CEILING(sq.slsqty / NULLIF(sq.Frequence, 0)) ELSE CEILING((sq.slsqty / 90.0) * @minday) END AS minqty, CASE WHEN CEILING((sq.slsqty / 90.0) * @maxday) < m.MaxSalesQtyInBill THEN m.MaxSalesQtyInBill ELSE CEILING((sq.slsqty / 90.0) * @maxday) END AS maxqty, CASE WHEN CEILING((sq.slsqty / 90.0) * @minday) <= maxQtyInPeriod.Maxsaleqty THEN 'Single Day Sales Greater than MinQty' ELSE 'Regular Order Based Min & Max' END AS Wantedtype, sq.Frequence, l.lastsaledate, l.LastReceivedDate FROM products p INNER JOIN SalesQuantity sq ON p.productcode = sq.productcode AND p.storename = sq.StoreName LEFT JOIN MaxSalesQty m ON p.productcode = m.Productcode LEFT JOIN (SELECT pt.Productcode, MAX(pt.LastBillDate) AS lastsaledate, MAX(pt.LastgrnDate) AS LastReceivedDate, pt.StoreName FROM ProductTrans pt WHERE pt.lastbilldate >= DATEADD(day, -20, GETDATE()) AND pt.LastBillDate IS NOT NULL AND pt.storename = @storename GROUP BY pt.Productcode, pt.StoreName) l ON p.productcode = l.Productcode LEFT JOIN (SELECT Productcode, MAX(sales) AS Maxsaleqty FROM (SELECT SUM(Quantity) AS sales, Productcode FROM ProductSaleInformation WHERE SeriesTransID = 1 AND transactionvalidity = 0 AND Transactiondate >= @ODATA AND storename = @storename GROUP BY Productcode) AS sales_summary GROUP BY Productcode) maxQtyInPeriod ON p.productcode = maxQtyInPeriod.Productcode), MaxSaleInfo AS (SELECT T.Productcode, T.Maxsaleqty, T.Transactiondate, T.storename FROM (SELECT Productcode, MAX(sales) AS Maxsaleqty, Transactiondate, storename FROM (SELECT SUM(Quantity) AS sales, Productcode, Transactiondate, psi.storename, ROW_NUMBER() OVER(PARTITION BY Productcode ORDER BY SUM(Quantity) DESC) AS rn FROM ProductSaleInformation psi WHERE psi.SeriesTransID = 1 AND psi.transactionvalidity = 0 AND psi.Transactiondate > @ODATA AND psi.storename = @storename GROUP BY Productcode, Transactiondate, psi.storename) subquery WHERE rn = 1 GROUP BY Productcode, Transactiondate, storename) T) SELECT ps.productcode, ps.productname, ps.minqty, ps.maxqty, ps.TotalStock, ps.slsqty, ps.producttype, ps.lastsaledate, ps.LastReceivedDate, m.Maxsaleqty, m.Transactiondate, ps.wanteddate, ps.StoreName, @storecode AS storecode, ps.OrderID, ps.SaleUnit, ps.PurchasePrice, ps.MRP, ps.UnitDescription, ps.SubLocation, CASE WHEN ps.TotalStock = 0 AND ROUND(((ps.maxqty - ps.TotalStock) / NULLIF(ps.SaleUnit, 0)), 0) = 0 THEN 'Rare Moment' WHEN CEILING(CASE WHEN ps.minqty < ps.AvgSalesQty THEN ps.AvgSalesQty ELSE ps.minqty END) < m.Maxsaleqty THEN 'Min & Max Based MaxsaleQTY' WHEN ps.slsqty = m.Maxsaleqty AND m.Maxsaleqty = CASE WHEN ps.minqty < ps.AvgSalesQty THEN ps.AvgSalesQty ELSE ps.minqty END AND ps.Frequence = 1 THEN 'Once Sold Last 90 days' ELSE 'Regular Order Based Min & Max' END AS Wantedtype, CASE WHEN ps.producttype = 0 THEN 0 ELSE 1 END AS productType, CASE WHEN ps.producttype = 0 THEN 'Non Pharma' ELSE 'Pharma' END AS producttypename, ps.Frequence, ps.AvgSalesQty, ps.MaxSalesQtyInBill, CASE WHEN ps.TotalStock = 0 AND (ps.maxqty - ps.TotalStock) <= 0 THEN 1 WHEN ps.SaleUnit > 0 THEN CEILING((ps.maxqty - ps.TotalStock) / ps.SaleUnit) ELSE 0 END AS Orderqty, @status AS status FROM ProductSaleInfo ps LEFT JOIN MaxSaleInfo m ON ps.productcode = m.Productcode AND ps.StoreName = m.StoreName WHERE ps.lastsaledate >= DATEADD(day, -10, GETDATE()) AND (ps.maxqty - ps.TotalStock) / NULLIF(ps.SaleUnit, 0) > 0 AND ps.minqty > ps.TotalStock AND ps.lastsaledate >= ps.LastReceivedDate AND ps.StoreName = @storename UNION ALL SELECT ps.productcode, ps.productname, 1 AS minqty, 1 AS maxqty, ps.TotalStock, ps.slsqty, ps.producttype, ps.lastsaledate, ps.LastReceivedDate, m.Maxsaleqty, m.Transactiondate, ps.wanteddate, ps.StoreName, ps.storecode, ps.OrderID, ps.SaleUnit, ps.PurchasePrice, ps.MRP, ps.UnitDescription, ps.SubLocation, 'Additional Row' AS Wantedtype, CASE WHEN ps.producttype = 0 THEN 0 ELSE 1 END AS productType2, CASE WHEN ps.producttype = 0 THEN 'Non Pharma' ELSE 'Pharma' END AS producttypename, ps.Frequence, ps.AvgSalesQty, ps.MaxSalesQtyInBill, 1 AS Orderqty, @status AS status FROM ProductSaleInfo ps LEFT JOIN MaxSaleInfo m ON ps.productcode = m.Productcode WHERE ps.TotalStock <= 1 AND ps.minqty <= 1 AND ps.Frequence > 1 AND ps.slsqty > 1 AND ps.lastsaledate >= DATEADD(day, -10, GETDATE()) AND ps.lastsaledate > ps.LastReceivedDate AND ps.StoreName = @storename AND NOT EXISTS (SELECT 1 FROM ProductSaleInfo WHERE productcode = ps.productcode AND (ps.maxqty - ps.TotalStock) / NULLIF(ps.SaleUnit, 0) > 0 AND ps.minqty > ps.TotalStock AND storename = @storename) ORDER BY ps.productname;
